values ('dialog_fq_star_003', 'fq_star_003', 'npc_centurion_valka', 'greeting', '[{"id": "greeting", "text": "Legionnaire. Fight on Any Terrain — Centurion Valka''s first lesson to every new Legion recruit, delivered with ...", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Grand Justiciar Aurelius wrote the code in our home star''s ashes. It has never been wrong. When it says advance, we advance. Today it says: prove your worth.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Defeat 6x Scorched Scarab; Collect 3x scarab_shell\n\nThe code is clear. Execution is mandatory.\n\nRewards: 70 EXP · 40 Currency · 40 Reputation · Rust Chitin", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 631)
