values ('dialog_fq_star_005', 'fq_star_005', 'npc_legion_class_trainer', 'greeting', '[{"id": "greeting", "text": "Legionnaire. The Forge That Shapes a Weapon — Centurion Valka summons you to Fortress Kaelen for the specialization rite ...", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Grand Justiciar Aurelius wrote the code in our home star''s ashes. It has never been wrong. When it says advance, we advance. Today it says: prove your worth.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Mission parameters: Speak with npc_legion_class_trainer; Speak with class_change_screen; Defeat 3x Dune Scavenger\n\nComplete with the honor the code demands.\n\nRewards: 400 EXP · 200 Currency · 150 Reputation · Wpn Iron Sword + Arm Iron Plate", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 633)
