values ('dialog_fq_star_007', 'fq_star_007', 'npc_centurion_valka', 'greeting', '[{"id": "greeting", "text": "The code demands action. Ash Hounds are fire given form and instinct", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Legion''s history is written in blood of those before us. Every Legionnaire adds a chapter. Make yours worth reciting.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Defeat 5x Ash Hound; Collect 3x ember_fang\n\nThe code is clear. Execution is mandatory.\n\nRewards: 120 EXP · 70 Currency · 70 Reputation · Animal Fang", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 635)
