values ('dialog_fq_star_036', 'fq_star_036', 'npc_centurion_valka', 'greeting', '[{"id": "greeting", "text": "Stand ready. Aethel Rift Stalkers are using the Cradle Expanse''s electromagnetic current...", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Legion''s history is written in blood of those before us. Every Legionnaire adds a chapter. Make yours worth reciting.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Mission parameters: Defeat 6x Aethel Rift Stalker; Defeat 3x Aethel Void Channeler\n\nComplete with the honor the code demands.\n\nRewards: 2350 EXP · 1175 Currency · 725 Reputation · Aethel Core Shard", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 664)
