values ('dialog_fq_star_039', 'fq_star_039', 'npc_centurion_valka', 'greeting', '[{"id": "greeting", "text": "Legionnaire. The Void''s Counter-Offensive Must Fail — The Aethel Abyssal Reavers and Void Channelers have mounted a coordinated i...", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Grand Justiciar Aurelius wrote the code in our home star''s ashes. It has never been wrong. When it says advance, we advance. Today it says: prove your worth.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Defeat 6x Aethel Abyssal Reaver; Defeat 3x Aethel Void Channeler\n\nThe code is clear. Execution is mandatory.\n\nRewards: 2500 EXP · 1250 Currency · 606 CRD · 770 Reputation · Aethel Core Shard", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 667)
