values ('dialog_fq_star_041', 'fq_star_041', 'npc_centurion_valka', 'greeting', '[{"id": "greeting", "text": "Legionnaire. The Legion Descends Into the Darkness — Grand Justiciar Aurelius describes the Void Echo Chasm to new arrivals with...", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Starforged Legion crossed the void after our homeworld was destroyed. Billions lost. Everything lost. But the code survived. Every mission declares: the Legion endures.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Mission parameters: Travel to VOID_ECHO_CHASM; Collect 3x void_channeler_core\n\nComplete with the honor the code demands.\n\nRewards: 2600 EXP · 1300 Currency · 630 CRD · 800 Reputation · Aethel Core Shard", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 669)
