values ('dialog_fq_star_052', 'fq_star_052', 'npc_centurion_valka', 'greeting', '[{"id": "greeting", "text": "Legionnaire. The Stalker That Hides in the Shard''s Blind Spot — A Void Stalker has taken up residence in the Chasm''s electromagnetic blind spot", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Legion''s history is written in blood of those before us. Every Legionnaire adds a chapter. Make yours worth reciting.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Mission parameters: Defeat 1x Void Stalker; Collect 1x core_fragment\n\nComplete with the honor the code demands.\n\nRewards: 3200 EXP · 1600 Currency · 774 CRD · 980 Reputation · Aethel Core Shard", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 680)
