values ('dialog_fq_star_053', 'fq_star_053', 'npc_centurion_valka', 'greeting', '[{"id": "greeting", "text": "Stand ready. Three Chrono Wraiths in the Chasm''s deep zone have created overlapping temp...", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Grand Justiciar Aurelius wrote the code in our home star''s ashes. It has never been wrong. When it says advance, we advance. Today it says: prove your worth.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Defeat 3x Chrono Wraith; Collect materials\n\nThe code is clear. Execution is mandatory.\n\nRewards: 3250 EXP · 1625 Currency · 786 CRD · 995 Reputation · Aethel Core Shard", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 681)
