values ('dialog_fq_star_068', 'fq_star_068', 'npc_centurion_valka', 'greeting', '[{"id": "greeting", "text": "The code demands action. Aethel Rift Stalkers have found the Siphon Core''s micro-fractures", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Grand Justiciar Aurelius wrote the code in our home star''s ashes. It has never been wrong. When it says advance, we advance. Today it says: prove your worth.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Defeat 6x Aethel Rift Stalker; Collect 1x Raw Aethel Fragment\n\nThe code is clear. Execution is mandatory.\n\nRewards: 3950 EXP · 1975 Currency · 954 CRD · 1205 Reputation · Aethel Core Shard", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 696)
