values ('dialog_fq_star_069', 'fq_star_069', 'npc_centurion_valka', 'greeting', '[{"id": "greeting", "text": "The code demands action. Deep in the Aethel Siphon Core, the entity that all other factions'' intelli...", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Legion''s history is written in blood of those before us. Every Legionnaire adds a chapter. Make yours worth reciting.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Mission parameters: Collect 3x core_fragment; Defeat 1x Gigantic Jotunn\n\nComplete with the honor the code demands.\n\nRewards: 4000 EXP · 2000 Currency · 966 CRD · 1220 Reputation · Aethel Core Shard", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 697)
