values ('dialog_fq_star_070', 'fq_star_070', 'npc_centurion_valka', 'greeting', '[{"id": "greeting", "text": "Stand ready. A Gravity Titan in the Cradle Expanse has been disrupting the Legion''s supp...", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Starforged Legion crossed the void after our homeworld was destroyed. Billions lost. Everything lost. But the code survived. Every mission declares: the Legion endures.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Defeat 1x Gravity Titan; Defeat 5x Aethel Abyssal Reaver\n\nThe code is clear. Execution is mandatory.\n\nRewards: 4050 EXP · 2025 Currency · 978 CRD · 1235 Reputation · Aethel Core Shard", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 698)
