values ('dialog_fq_star_084', 'fq_star_084', 'npc_centurion_valka', 'greeting', '[{"id": "greeting", "text": "Legionnaire. Sacred Duty — Legion duty.", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Legion''s history is written in blood of those before us. Every Legionnaire adds a chapter. Make yours worth reciting.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Defeat 5x Aethel Abyssal Reaver\n\nThe code is clear. Execution is mandatory.\n\nRewards: 5000 EXP · 2500 Currency · 1250 CRD · 2000 Reputation", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 712)
